VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := Motor_Running AND (Motor_Current > 47.7), PT := T#10S);

IF Motor_Winding_Temp > 145.0 OR Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

IF Motor_Winding_Temp > 130.0 OR Motor_Current > 41.5 THEN
    Overload_Alarm := TRUE;
END_IF;

IF Safe_Mode_Active AND Motor_Speed > 900.0 THEN
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Motor_Stop := FALSE;
    Overload_Alarm := FALSE;
END_IF;

